<?php namespace App\Domains\Core\Requests\Auth; use App\Http\Requests\ApiFormRequest; class UpdateProfileRequest extends ApiFormRequest { public function authorize(): bool { return true; } public function rules(): array { return ["name" => "sometimes|required|string|max:100", "email" => "sometimes|required|email|max:100|unique:users,email," . $this->user()->id, "first_name" => "sometimes|nullable|string|max:50", "last_name" => "sometimes|nullable|string|max:50", "phone" => "nullable|string|max:20", "avatar" => "nullable|string|max:255"]; } }
